    await dialog.getByText('Version 9').waitFor();
    await dialog.getByRole('button', { name: 'Import job test-job' }).click();
    await page.getByRole('heading', { name: 'Imports', exact: true }).waitFor();
    await page.getByText('test-job', { exact: true }).waitFor();
    assert.deepEqual(pageErrors, []);
    console.log('Frame detail browser smoke passed.');
  } finally {
    await browser?.close();
    server.kill();
  }
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
