import type { ReactElement } from 'react'
import { FrameDetail } from '../../frame-detail'
import { frameIdFromSegment } from '../../frame-route'

export default async function FramePage({
  params,
}: {
  params: Promise<{ frameId: string }>
}): Promise<ReactElement> {
  const { frameId: segment } = await params
  return <FrameDetail frameId={frameIdFromSegment(segment)} />
}

export function frameDetailHref(frameId: string): string {
  // Browsers normalize dot segments, even when the dots are percent-encoded.
  const segment = frameId === '.' || frameId === '..' || frameId.startsWith('~')
    ? `~${frameId}`
    : frameId
  return `/frames/${encodeURIComponent(segment)}`
}

export function frameIdFromSegment(segment: string): string {
  return segment === '~.' || segment === '~..' || segment.startsWith('~~')
    ? segment.slice(1)
    : segment
}

